// The slide classes the ENGINE owns, which a saved component may not take as its name
// (`finish`, `print`, `dark`, the modifiers, the `tint-*`/`mark-*` families). Generated by
// tools/build-packages-index.js; the CLI's registry reads the same file (lib/packages/index.js).
//
// Its own module, loaded by `import()` from the save and import paths only: the list is
// ~5 KB and the Studio's eager bundle has a byte budget (docs/route-budget.json). Every
// caller is already async.

// Default import: the docs dev server interops only a default import of a CJS leaf.
import reserved from '../../../../../lib/packages/reserved-classes.generated.js';
import { RESERVED_COMPONENT_NAMES, RESERVED_SUFFIX } from './reserved-names';

const { names, prefixes } = reserved as { names: string[]; prefixes: string[] };
const NAMES: ReadonlySet<string> = new Set(names);

/** True when a component under this name would take a class the engine owns. */
export function isEngineClass(name: string): boolean {
	// A `-custom` name is the escape hatch itself, so reserving stays idempotent.
	if (name.endsWith(RESERVED_SUFFIX)) return false;
	return NAMES.has(name) || prefixes.some((p) => name === p || name.startsWith(p.endsWith('-') ? p : `${p}-`));
}

/** The name a component is saved under: shipped components AND engine classes are reserved. */
export function unreservedComponentName(name: string): string {
	return RESERVED_COMPONENT_NAMES.has(name) || isEngineClass(name) ? `${name}${RESERVED_SUFFIX}` : name;
}
